import os, json, hashlib, numpy as np

N = 26
SAFETY = 1e-9
P_C = 'storage/noesis/latest_centers.txt'
P_R = 'storage/noesis/latest_radii.txt'
OUT = 'storage/noesis/exports/checksums.json'

def sha256_file(path):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()

def load_snapshot():
    c = np.loadtxt(P_C, dtype=float).reshape(N,2)
    r = np.loadtxt(P_R, dtype=float).reshape(N,)
    return c, r

def construct_packing():
    c, r = load_snapshot()
    data = {}
    try:
        data['latest_centers.txt'] = sha256_file(P_C)
        data['latest_radii.txt']   = sha256_file(P_R)
        os.makedirs(os.path.dirname(OUT), exist_ok=True)
        with open(OUT, 'w') as f:
            json.dump(data, f, indent=2)
    except Exception:
        pass
    return c.astype(float), np.maximum(r - SAFETY, 1e-9).astype(float)
